// src/core/logger.ts
var LOG_LEVELS = {
  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3,
  NONE: 4
};
var _logLevel = "INFO";
var _disabled = false;
function _getConfiguredLevel() {
  const envLevel = process.env.NEATLOGS_LOG_LEVEL?.toUpperCase();
  if (envLevel && envLevel in LOG_LEVELS) {
    return envLevel;
  }
  return "INFO";
}
_logLevel = _getConfiguredLevel();
function getLogger() {
  return {
    debug(message, ...args) {
      if (!_disabled && LOG_LEVELS[_logLevel] <= LOG_LEVELS.DEBUG) {
        console.debug(`[neatlogs] ${message}`, ...args);
      }
    },
    info(message, ...args) {
      if (!_disabled && LOG_LEVELS[_logLevel] <= LOG_LEVELS.INFO) {
        console.info(`[neatlogs] ${message}`, ...args);
      }
    },
    warn(message, ...args) {
      if (!_disabled && LOG_LEVELS[_logLevel] <= LOG_LEVELS.WARN) {
        console.warn(`[neatlogs] ${message}`, ...args);
      }
    },
    error(message, ...args) {
      if (!_disabled && LOG_LEVELS[_logLevel] <= LOG_LEVELS.ERROR) {
        console.error(`[neatlogs] ${message}`, ...args);
      }
    }
  };
}
function enableDebugLogging() {
  _logLevel = "DEBUG";
}
function disableLogging() {
  _disabled = true;
}
function enableLogging() {
  _disabled = false;
}

// src/span-kinds/constants.ts
var VECTOR_DB_SYSTEMS = /* @__PURE__ */ new Set([
  "chroma",
  "chromadb",
  "pinecone",
  "qdrant",
  "milvus",
  "marqo",
  "weaviate",
  "lancedb",
  "pgvector",
  "elasticsearch"
]);
var RETRIEVAL_OPS = [
  "query",
  "search",
  "get",
  "fetch",
  "find",
  "retrieve",
  "scroll",
  "peek",
  "discover",
  "recommend",
  "aggregate",
  "hybrid_search",
  "select"
];
var VECTOR_DB_NAMES = [
  "chroma",
  "pinecone",
  "weaviate",
  "qdrant",
  "milvus",
  "lancedb",
  "marqo"
];

// src/span-kinds/mapping.ts
var VALID_SPAN_KINDS = /* @__PURE__ */ new Set([
  "WORKFLOW",
  "AGENT",
  "CHAIN",
  "TOOL",
  "RETRIEVER",
  "EMBEDDING",
  "MCP_TOOL",
  "GUARDRAIL",
  "EVALUATOR"
]);
var ALL_SPAN_KINDS = /* @__PURE__ */ new Set([
  ...VALID_SPAN_KINDS,
  "LLM",
  "RERANKER",
  "VECTOR_STORE"
]);
function resolveExplicitSpanKind(attributes) {
  for (const key of [
    "neatlogs.span.kind",
    "openinference.span.kind",
    "traceloop.span.kind"
  ]) {
    const value = String(attributes[key] ?? "").trim();
    if (value) return value;
  }
  return "";
}
function inferSpanKindFromName(spanName) {
  const nameLower = spanName.toLowerCase();
  if (["openai", "anthropic", "cohere", "bedrock", "chat", "completion", "llm", "gemini", "google_genai"].some(
    (kw) => nameLower.includes(kw)
  )) {
    return "LLM";
  }
  if (nameLower.includes("embed")) {
    return "EMBEDDING";
  }
  if (VECTOR_DB_NAMES.some((db) => nameLower.includes(db))) {
    if (RETRIEVAL_OPS.some((kw) => nameLower.includes(kw))) {
      return "RETRIEVER";
    }
    return "VECTOR_STORE";
  }
  if (["retriev", "search", "query"].some((kw) => nameLower.includes(kw))) {
    return "RETRIEVER";
  }
  if (nameLower.includes("rerank")) {
    return "RERANKER";
  }
  if (nameLower.includes("agent")) {
    return "AGENT";
  }
  if (["tool", "function"].some((kw) => nameLower.includes(kw))) {
    return "TOOL";
  }
  if (["guardrail", "validate", "moderate", "safety"].some((kw) => nameLower.includes(kw))) {
    return "GUARDRAIL";
  }
  if (["evaluat", "score", "metric"].some((kw) => nameLower.includes(kw))) {
    return "EVALUATOR";
  }
  return "CHAIN";
}

